import math

def _is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    limit = int(math.isqrt(n))
    for i in range(3, limit + 1, 2):
        if n % i == 0:
            return False
    return True

def prime_length(s: str) -> bool:
    """Return True if the length of *s* is a prime number, False otherwise."""
    return _is_prime(len(s))
